import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Rhythm Ledger Template","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/rhythm-ledger.en.md","filePath":"public/downloads/worksheets/rhythm-ledger.en.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/rhythm-ledger.en.md"};function o(d,e,s,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="rhythm-ledger-template" tabindex="-1">Rhythm Ledger Template <a class="header-anchor" href="#rhythm-ledger-template" aria-label="Permalink to &quot;Rhythm Ledger Template&quot;">​</a></h1><p>Copy this ledger into a private note and use one page each week. It is not a streak table or a dashboard for scoring your character. It helps you see what deserves to stay, which condition needs to change, and how to return after an interruption.</p><p>If the ledger has identified an obstacle, use the troubleshooting table and two examples in <a href="https://byoungd.github.io/up/en/threads/practice/discipline-and-consistency" target="_blank" rel="noreferrer">Discipline and Consistency in Practice</a>, then define one change and its acceptance criteria in a <a href="https://byoungd.github.io/up/en/templates/consistency-plan" target="_blank" rel="noreferrer">Consistency Plan</a>. That experiment card supplements this ledger. Return its conclusion to “This Week&#39;s Decision” without maintaining a separate schedule.</p><p>Do not write passwords, identity documents, customer data, medical privacy, or unauthorised third-party information. When safety, health, money, or relationship risks are involved, contact a qualified professional or a trusted support person first.</p><h2 id="_1-one-main-question" tabindex="-1">1. One Main Question <a class="header-anchor" href="#_1-one-main-question" aria-label="Permalink to &quot;1. One Main Question&quot;">​</a></h2><p>Date range:<br> The one question this week:<br> Real situation and audience:<br> Acceptance standard:<br> Baseline evidence at the start of the week:</p><p>The question should be observable, such as “Can I explain a project risk in English without a script and answer a follow-up?” Do not write “be better this week”.</p><h2 id="_2-three-capacity-versions" tabindex="-1">2. Three Capacity Versions <a class="header-anchor" href="#_2-three-capacity-versions" aria-label="Permalink to &quot;2. Three Capacity Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capacity</th><th>When to use it</th><th>Minimum action</th><th>Evidence that must remain</th><th>Stop or downgrade condition</th></tr></thead><tbody><tr><td>Full day</td><td>Time and capacity are relatively stable</td><td></td><td></td><td></td></tr><tr><td>Compressed day</td><td>Time is short or attention is fragmented</td><td></td><td></td><td></td></tr><tr><td>Recovery day</td><td>Illness, sleeplessness, grief, or responsibility rises sharply</td><td></td><td></td><td></td></tr></tbody></table><p>The three versions serve one direction. A recovery day is not a failure. When safety, sleep, the body, or relationships are clearly affected, protect those limits before completing the plan.</p><h2 id="_3-give-repetition-an-echo" tabindex="-1">3. Give Repetition an Echo <a class="header-anchor" href="#_3-give-repetition-an-echo" aria-label="Permalink to &quot;3. Give Repetition an Echo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Action</th><th>Recall / variation / output / feedback</th><th>What new information appeared?</th><th>Which variable changes next time?</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>If four repetitions produce no new information, change the topic, listener, time limit, number of prompts, or tool permission before simply adding more repetitions.</p><h2 id="_4-record-one-useful-piece-of-feedback" tabindex="-1">4. Record One Useful Piece of Feedback <a class="header-anchor" href="#_4-record-one-useful-piece-of-feedback" aria-label="Permalink to &quot;4. Record One Useful Piece of Feedback&quot;">​</a></h2><p>Who or what provided the feedback:<br> Observation: What did the person actually see, hear, or measure?<br> Impact: How did it affect understanding, use, or the result?<br> Next adjustment: Which one important variable will I change?<br> Evidence location:</p><p>When asking AI for feedback, submit your own version first. Ask for no more than three issues that affect the result, and require a distinction between observation, inference, and suggestion. A person decides what to accept.</p><h2 id="_5-interruption-and-return" tabindex="-1">5. Interruption and Return <a class="header-anchor" href="#_5-interruption-and-return" aria-label="Permalink to &quot;5. Interruption and Return&quot;">​</a></h2><p>What happened, as facts (no character judgment):<br> Which condition changed: time / capacity / difficulty / environment / responsibility<br> The smallest return action within 24 hours:<br> What I will explicitly not make up:<br> Who I need to contact or which risk needs escalation:</p><p>If the same resistance appears three times, change the time box, task size, environment, boundary, or support network. Do not repay an interruption with sleep deprivation or shame.</p><h2 id="_6-this-week-s-decision" tabindex="-1">6. This Week&#39;s Decision <a class="header-anchor" href="#_6-this-week-s-decision" aria-label="Permalink to &quot;6. This Week&#39;s Decision&quot;">​</a></h2><p>One design I will keep:<br> One demand or entry point I will remove:<br> One condition I will change next week:<br> One number I will stop tracking:<br> Next review date:<br> First action when I open the file next time:</p><h2 id="_7-handover-and-evidence-locations" tabindex="-1">7. Handover and Evidence Locations <a class="header-anchor" href="#_7-handover-and-evidence-locations" aria-label="Permalink to &quot;7. Handover and Evidence Locations&quot;">​</a></h2><p>First version:<br> Revised version:<br> Feedback or retest:<br> Next task: owner / date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-4/rhythm-and-compounding" target="_blank" rel="noreferrer">Rhythm: Let Small Things Travel Through Time</a> | <a href="https://byoungd.github.io/up/en/threads/part-4/daily-system" target="_blank" rel="noreferrer">Daily System: Put Change into the Day</a> | <a href="https://byoungd.github.io/up/en/templates/weekly-review" target="_blank" rel="noreferrer">Weekly Review Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-19. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',26)])])}const b=t(i,[["render",o]]);export{u as __pageData,b as default};
